export function assert_filter_text(aText) {
  const textbox = get_about_3pane()
    .document.getElementById("qfb-qs-textbox")
    .shadowRoot.querySelector("input");
  if (textbox.value != aText) {
    throw new Error(
      "Expected text filter value of '" +
        aText +
        "' but got '" +
        textbox.value +
        "'"
    );
  }
}
